#!/usr/bin/env node
// pnpm api:types [--check]: the web app's API types (apps/web/src/lib/api.gen.ts), generated by
// openapi-typescript from the API's OpenAPI document (the same Zod schemas that validate requests).
// Run from the repo root. Own package: openapi-typescript needs TypeScript 5 (package.json).
// --check (part of `pnpm check`) fails when the committed file is stale: run `pnpm api:types`.
import { readFileSync, writeFileSync } from 'node:fs';
import openapiTS, { astToString } from 'openapi-typescript';

const OUT = 'apps/web/src/lib/api.gen.ts';
const { buildApp } = await import('../../apps/api/src/app.ts');
const app = await buildApp();
await app.ready();
const spec = app.swagger();

const generated = `// Generated by \`pnpm api:types\` from the API's OpenAPI document. Do not edit.\n${astToString(await openapiTS(spec))}`;
if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(OUT, 'utf8');
  } catch {}
  if (current !== generated) {
    console.error(`${OUT} is stale: run \`pnpm api:types\` and commit the result.`);
    process.exit(1);
  }
  console.log(`${OUT} is up to date`);
} else {
  writeFileSync(OUT, generated);
  console.log(`wrote ${OUT}`);
}
process.exit(); // the app's Redis and database clients would keep the process alive
